import sqlite3
from typing import Optional, Tuple, List, Any

def execute_query(query: str, parameters: Optional[Tuple] = None) -> Optional[List[Any]]:
    try:
        conn = sqlite3.connect('./Test/CWE-89_01/example.db')
        cursor = conn.cursor()

        if parameters:
            cursor.execute(query, parameters)
        else:
            cursor.execute(query)

        if query.strip().upper().startswith('SELECT'):
            result = cursor.fetchall()
        else:
            conn.commit()
            result = None

        cursor.close()
        conn.close()
        return result
    except sqlite3.Error as e:
        raise e
